        nums = []
        for char in s:
            if char.isdigit():
                nums.append(int(char))
        nums = [num for num in nums if num != max(nums)]
        if len(nums) >= 1: return max(nums)
        else: return -1

class Solution:
    def secondHighest(self, s: str) -> int:
        first = second = -1
        for c in s:
            if not c.isdigit():
                continue
            d = int(c)
            if d > first:
                first, second = d, first
            elif first > d > second:
                second = d
        return second

